//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut delay_ms = config.base_delay_ms.min(config.max_delay_ms);

    for attempt in 0..max_attempts {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() => return Err(error),
            Err(error) => {
                if attempt + 1 == max_attempts {
                    return Err(error);
                }
                sleeper.sleep_ms(delay_ms);
                delay_ms = delay_ms.saturating_mul(2).min(config.max_delay_ms);
            }
        }
    }

    unreachable!("max_attempts is clamped to at least one")
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::cell::Cell;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let attempts = Cell::new(0);
        let result = run_job(&config(5, 10, 25), &mut sleeper, || {
            let attempt = attempts.get() + 1;
            attempts.set(attempt);
            Err(RetryError::Transient(format!("attempt {attempt}")))
        });

        assert_eq!(result, Err(RetryError::Transient("attempt 5".into())));
        assert_eq!(attempts.get(), 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying_or_sleeping() {
        let mut sleeper = FakeSleeper::default();
        let attempts = Cell::new(0);
        let result = run_job(&config(4, 10, 100), &mut sleeper, || {
            attempts.set(attempts.get() + 1);
            Err(RetryError::Permanent("invalid job".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
        assert_eq!(attempts.get(), 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn saturates_delay_without_overflow() {
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&config(3, u64::MAX, u64::MAX), &mut sleeper, || {
            Err(RetryError::Transient("unavailable".into()))
        });

        assert!(result.is_err());
        assert_eq!(sleeper.sleeps, vec![u64::MAX, u64::MAX]);
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let attempts = Cell::new(0);
        let result = run_job(&config(1, 10, 100), &mut sleeper, || {
            attempts.set(attempts.get() + 1);
            Err(RetryError::Transient("unavailable".into()))
        });

        assert!(result.is_err());
        assert_eq!(attempts.get(), 1);
        assert!(sleeper.sleeps.is_empty());
    }
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

# jobrunner

Small job runner with a pluggable, bounded exponential retry policy.

## Retry policy

`run_job` makes at most `max_attempts` calls, where the first call counts as
an attempt. Only `RetryError::Transient` failures are retried; permanent
failures are returned immediately. Before each retry it sleeps for
`base_delay_ms`, then doubles the delay for the next retry. Delays are capped
at `max_delay_ms` (and arithmetic saturates safely at the cap).

For example:

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig {
    max_attempts: 4,
    base_delay_ms: 100,
    max_delay_ms: 500,
};
let mut sleeper = FakeSleeper::default();
let mut attempts = 0;

run_job(&config, &mut sleeper, || {
    attempts += 1;
    if attempts < 3 {
        Err(RetryError::Transient("temporary outage".into()))
    } else {
        Ok(())
    }
})?;

assert_eq!(sleeper.sleeps, vec![100, 200]);
# Ok::<(), RetryError>(())
```

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_until_success() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 5,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        if attempts < 3 {
            Err(RetryError::Transient("temporary outage".into()))
        } else {
            Ok(())
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 3);
    assert_eq!(sleeper.sleeps, vec![5, 10]);
}

#[test]
fn public_api_does_not_retry_permanent_errors() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 5,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(attempts, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn public_api_counts_first_call_in_max_attempts() {
    let config = RetryConfig {
        max_attempts: 2,
        base_delay_ms: 5,
        max_delay_ms: 20,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Transient("temporary outage".into()))
    });

    assert_eq!(
        result,
        Err(RetryError::Transient("temporary outage".into()))
    );
    assert_eq!(attempts, 2);
    assert_eq!(sleeper.sleeps, vec![5]);
}
